mainStatements.restrictedTemplate:
module acrMainModule '{{moduleReference}}' = if (acrMain.deploy) {
  name: 'acrMain-${target.code}-${uniqueString(acrMain.name)}'
  scope: rg_main
  params: {
    name: acrMain.name
    location: acrMain.location
    acrSku: acrMain.acrSku
    acrAdminUserEnabled: acrMain.adminUserEnabled
    anonymousPullEnabled: acrMain.anonymousPullEnabled
    publicNetworkAccess: acrMain.publicNetworkAccess
    networkRuleSetDefaultAction: acrMain.networkRuleSetDefaultAction
    networkRuleSetIpRules: [
      for ipRange in acrMain.allowedIpRanges: {
        action: 'Allow'
        value: ipRange
      }
    ]
    tags: acrMain.tags
    diagnosticSettings: []
    enableTelemetry: false
  }
}

mainStatements.template:
module appDeliveryAcrPush './registry-role-assignment.bicep' = if (acrMain.deploy && !empty(appDeliveryPrincipalId)) {
  name: 'appDeliveryAcrPush-${target.code}-${uniqueString(acrMain.name)}'
  scope: resourceGroup(target.subscriptionId, resourceGroups.main.name)
  params: {
    registryName: acrMain.name
    principalId: appDeliveryPrincipalId
    roleDefinitionId: subscriptionResourceId(
      target.subscriptionId,
      'Microsoft.Authorization/roleDefinitions',
      acrPushRoleId
    )
  }
  dependsOn: [
    acrMainModule
  ]
}

helpers.template:
targetScope = 'resourceGroup'

@description('Nom du registre existant qui reçoit le rôle.')
param registryName string

@description('Object ID du principal auquel le rôle est attribué.')
param principalId string

@description('ID de définition du rôle intégré.')
param roleDefinitionId string

var acrPushRoleId = '{{role:AcrPush}}'

resource registry '{{resource:ContainerRegistry}}' existing = {
  name: registryName
}

resource appDeliveryAcrPush 'Microsoft.Authorization/roleAssignments@{{roleAssignmentApiVersion}}' = {
  name: guid(registry.id, principalId, acrPushRoleId)
  scope: registry
  properties: {
    roleDefinitionId: roleDefinitionId
    principalId: principalId
    principalType: 'ServicePrincipal'
  }
}
